        account = atm.Refused(account, W(40), AtmStatus.CannotDispense);              // 20×2 dans la cassette bloquée, 10×3 seulement
        account = atm.Ok(account, W(30), N(0, 0, 3), 0, A(70, 90), N(3, 3, 0));
