        Assert.Equal(new AtmResult(AtmStatus.Ok, Empty, 0, A(100, 50)),
            second.Execute(A(50, 50), D(1, 0, 0)));
        Assert.Equal(N(1, 1, 0), dispenser.Stock);

        Assert.Equal(new AtmResult(AtmStatus.Ok, N(1, 1, 0), 0, A(30, 120)),
